<?php
declare(strict_types=1);
$app=require dirname(__DIR__,3).'/bootstrap.php';$app['auth']->requireRole(['ADMIN']);$jobId=filter_input(INPUT_GET,'job',FILTER_VALIDATE_INT);$type=(string)($_GET['type']??'');if(!$jobId||!in_array($type,['pdf','xlsx'],true)){http_response_code(404);exit('Not found.');}
try{$column=$type.'_storage_key';$q=$app['pdo']->prepare("SELECT $column storage_key,period_start FROM dbo.annual_invoice_jobs WHERE id=:id AND artifact_status='READY'");$q->execute(['id'=>$jobId]);$row=$q->fetch();if(!$row)throw new RuntimeException('Eksporti nuk është ende gati.');$path=(new App\Document\JobArtifactStore(dirname(__DIR__,3).'/var/documents'))->path((string)$row['storage_key']);if(!is_readable($path))throw new RuntimeException('PHP-FPM nuk ka leje leximi për eksportin.');header('Content-Type: '.($type==='pdf'?'application/pdf':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'));header('Content-Disposition: attachment; filename="faturat-job-'.$jobId.'-'.$row['period_start'].'.'.$type.'"');header('Content-Length: '.filesize($path));header('Cache-Control: private, no-store');readfile($path);}
catch(Throwable $e){$reference=gmdate('YmdHis').'-'.bin2hex(random_bytes(3));error_log('Job artifact download '.$reference."\n".$e->__toString());http_response_code(503);header('Content-Type: text/plain; charset=UTF-8');echo 'Dokumenti nuk mund të shkarkohet. Referenca: '.$reference;}
